sys_variable_value.value:
(function execute(inputs, outputs) {
var inputsPayload = {};

// text is a input of type: string
inputsPayload['text'] = inputs.text;
inputsPayload['personality'] = inputs.personality;

var capabilityId = 'b4af289847212a50873506f1d16d4373'; 
var request = {
	executionRequests: [{
		payload: inputsPayload,
		capabilityId: capabilityId,
		meta: {
			skillConfigId: '01af289847212a50873506f1d16d43a4'
		}
	}], 
	mode: 'sync' 
};

try {
	var output = sn_one_extend.OneExtendUtil.execute(request)['capabilities'][request.executionRequests[0].capabilityId]['response'];
	outputs.results = JSON.parse(output).model_output;

	//var response = sn_one_extend.OneExtendUtil.execute(request) || {}; 
	//var skillResponse = ((response["capabilities"] || {})[capabilityId] || {})["response"]; 
	//outputs.results = JSON.stringify(skillResponse);
} catch(e) {
	//gs.error(e);
	outputs.results = 'Something went wrong while executing skill.' + e;
}
})(inputs, outputs);

